void sensfusion6UpdateQ(float gx, float gy, float gz, float ax, float ay, float az, float dt) { if (!sensfusion6IsInit) sensfusion6Init(); estimatedGravityDirection(qw, qx, qy, qz, &gravityX, &gravityY, &gravityZ); float norm = sqrtf(ax * ax + ay * ay + az * az); if (norm > 0.0f) { ax /= norm; ay /= norm; az /= norm; float ex = ay * gravityZ - az * gravityY; float ey = az * gravityX - ax * gravityZ; float ez = ax * gravityY - ay * gravityX; if (twoKi > 0.0f) { integralFBx += twoKi * ex * dt; integralFBy += twoKi * ey * dt; integralFBz += twoKi * ez * dt; gx += integralFBx; gy += integralFBy; gz += integralFBz; } else { integralFBx = integralFBy = integralFBz = 0.0f; } gx += twoKp * ex; gy += twoKp * ey; gz += twoKp * ez; if (!sensfusion6IsCalibrated) { baseZacc = ax * gravityX + ay * gravityY + az * gravityZ; sensfusion6IsCalibrated = true; } } gx *= (float)M_PI / 180.0f; gy *= (float)M_PI / 180.0f; gz *= (float)M_PI / 180.0f; float halfDt = 0.5f * dt; float w = qw, x = qx, y = qy, z = qz; qw += (-x * gx - y * gy - z * gz) * halfDt; qx += (w * gx + y * gz - z * gy) * halfDt; qy += (w * gy - x * gz + z * gx) * halfDt; qz += (w * gz + x * gy - y * gx) * halfDt; norm = invSqrt(qw * qw + qx * qx + qy * qy + qz * qz); if (norm > 0.0f) { qw *= norm; qx *= norm; qy *= norm; qz *= norm; } estimatedGravityDirection(qw, qx, qy, qz, &gravityX, &gravityY, &gravityZ); updateSensfusionLog(); }
