static bool stateCanFly(SupervisorState state) { return state == supervisorStateReadyToFly || state == supervisorStateFlying || state == supervisorStateWarningLevelOut || state == supervisorStateLanded; }
void supervisorInit(void) { supervisorState = supervisorStateLocked; supervisorConditionBits = 0; flightTick = 0; flightSeen = false; supSpinTick = 0; memset(&supSensor, 0, sizeof(supSensor)); memset(supRatios, 0, sizeof(supRatios)); memset(supRpm, 0, sizeof(supRpm)); }
