uint16_t supervisorGetInfoBitfield(void) { uint16_t bits = 0; if (supervisorCanArm()) bits |= (1U << 0); if (supervisorIsArmed()) bits |= (1U << 1); if (autoArm) bits |= (1U << 2); if (supervisorCanFly()) bits |= (1U << 3); if (supervisorConditionBits & SUPERVISOR_CB_IS_FLYING) bits |= (1U << 4); if (supervisorConditionBits & SUPERVISOR_CB_IS_TUMBLED) bits |= (1U << 5); if (!supervisorIsArmed()) bits |= (1U << 6); if (supervisorIsCrashed()) bits |= (1U << 7); if (supervisorConditionBits & SUPERVISOR_CB_DECK_FAULT) bits |= (1U << 11); return bits; }
bool isFlyingCheck(const uint32_t motorRatios[4], uint32_t idleThrust, uint32_t currentTick) { if (motorRatios) { for (int i = 0; i < 4; i++) { if (motorRatios[i] > idleThrust) { flightTick = currentTick; flightSeen = true; break; } } } return flightSeen && (uint32_t)(currentTick - flightTick) < IS_FLYING_HYSTERESIS_THRESHOLD; }
bool isTumbledCheck(float accX, float accY, float accZ, float crashDetectionGs, float freeFallThreshold, float acceptedTiltAccZ, float acceptedUpsideDownAccZ, uint32_t maxTiltTime, uint32_t maxUpsideDownTime, bool tumbleCheckEnabled, uint32_t currentTick, bool *isFreeFalling) { static uint32_t tiltStart; if (isFreeFalling) *isFreeFalling = false; float norm = sqrtf(accX * accX + accY * accY + accZ * accZ); if (crashDetectionGs > 0.0f && fabsf(norm - 1.0f) > crashDetectionGs) supervisorConditionBits |= SUPERVISOR_CB_CRASHED; if (fabsf(accX) < freeFallThreshold && fabsf(accY) < freeFallThreshold && fabsf(accZ) < freeFallThreshold) { if (isFreeFalling) *isFreeFalling = true; supervisorConditionBits |= SUPERVISOR_CB_FREE_FALL; tiltStart = 0; return false; } if (!tumbleCheckEnabled) return false; uint32_t limit = 0; if (accZ < acceptedUpsideDownAccZ) limit = maxUpsideDownTime; else if (accZ < acceptedTiltAccZ) limit = maxTiltTime; else { tiltStart = 0; return false; } if (tiltStart == 0U) tiltStart = currentTick == 0U ? 1U : currentTick; return (uint32_t)(currentTick - tiltStart) >= limit; }
bool checkEmergencyStopWatchdog(uint32_t currentTick, uint32_t lastNotificationTick) { return lastNotificationTick == 0U || (uint32_t)(currentTick - lastNotificationTick) <= DEFAULT_EMERGENCY_STOP_WATCHDOG_TIMEOUT; }
bool supervisorIsPreflightTimeout(SupervisorState state, uint32_t latestArmingTick, uint32_t currentTick, uint32_t preflightTimeoutDuration) { return state == supervisorStateReadyToFly && latestArmingTick != 0U && (uint32_t)(currentTick - latestArmingTick) >= preflightTimeoutDuration; }
