void supervisorSetSensorData(const SensorData *sensors) { if (sensors) supSensor = *sensors; }
void supervisorSetMotorRatios(const uint32_t motorRatios[4], uint32_t idleThrust) { if (motorRatios) memcpy(supRatios, motorRatios, sizeof(supRatios)); supIdle = idleThrust; }
void supervisorSetMotorRPMs(const int32_t motorRPMs[4]) { if (motorRPMs) memcpy(supRpm, motorRPMs, sizeof(supRpm)); }
void supervisorConfigureSafety(float crashDetectionGs, float freeFallThreshold, float acceptedTiltAccZ, float acceptedUpsideDownAccZ, uint32_t maxTiltTime, uint32_t maxUpsideDownTime, bool tumbleCheckEnabled) { crashGs = crashDetectionGs; freeFall = freeFallThreshold; tiltZ = acceptedTiltAccZ; upsideZ = acceptedUpsideDownAccZ; tiltTime = maxTiltTime; upsideTime = maxUpsideDownTime; tumbleEnabled = tumbleCheckEnabled; }
void supervisorConfigureArming(bool autoArming, uint32_t spinupTimeoutDurationMs) { autoArm = autoArming; spinTimeout = spinupTimeoutDurationMs; }
void supervisorUpdate(uint32_t stabilizerStep) { if (!RATE_DO_EXECUTE(RATE_SUPERVISOR, stabilizerStep)) return; bool free = false; if (isFlyingCheck(supRatios, supIdle, stabilizerStep)) supervisorConditionBits |= SUPERVISOR_CB_IS_FLYING; else supervisorConditionBits &= ~SUPERVISOR_CB_IS_FLYING; if (isTumbledCheck(supSensor.acc.x, supSensor.acc.y, supSensor.acc.z, crashGs, freeFall, tiltZ, upsideZ, tiltTime, upsideTime, tumbleEnabled, stabilizerStep, &free)) supervisorConditionBits |= SUPERVISOR_CB_IS_TUMBLED; if (free) supervisorState = supervisorStateExceptFreeFall; if (supervisorState == supervisorStateArming && spinTimeout != 0U) { if (supSpinTick == 0U) supSpinTick = stabilizerStep == 0U ? 1U : stabilizerStep; if ((uint32_t)(stabilizerStep - supSpinTick) >= spinTimeout) supervisorConditionBits |= SUPERVISOR_CB_SPINUP_TIMEOUT; } else { supSpinTick = 0; supervisorConditionBits &= ~SUPERVISOR_CB_SPINUP_TIMEOUT; } supervisorLog.info = supervisorGetInfoBitfield(); supervisorLog.accNorm = sqrtf(supSensor.acc.x * supSensor.acc.x + supSensor.acc.y * supSensor.acc.y + supSensor.acc.z * supSensor.acc.z); }

static EstimatorMeasurement eq[16];
static unsigned eh, et, ec;
bool estimatorEnqueue(const EstimatorMeasurement *measurement) { if (!measurement || ec >= 16U) return false; eq[et] = *measurement; et = (et + 1U) % 16U; ec++; return true; }
bool estimatorDequeue(EstimatorMeasurement *measurement) { if (!measurement || ec == 0U) return false; *measurement = eq[eh]; eh = (eh + 1U) % 16U; ec--; return true; }
void estimatorComplementary(uint32_t stabilizerStep) { EstimatorMeasurement m; while (estimatorDequeue(&m)) { if (m.type == MeasurementTypeGyroscope) { gyro.x = m.data[0]; gyro.y = m.data[1]; gyro.z = m.data[2]; } else if (m.type == MeasurementTypeAcceleration) { acc.x = m.data[0]; acc.y = m.data[1]; acc.z = m.data[2]; } else if (m.type == MeasurementTypeBarometer) { baro.pressure = m.data[0]; baro.temp = m.data[1]; baro.asl = m.data[2]; } } if (RATE_DO_EXECUTE(RATE_250_HZ, stabilizerStep)) { sensfusion6UpdateQ(gyro.x, gyro.y, gyro.z, acc.x, acc.y, acc.z, 1.0f / (float)SENSFUSION_RATE_HZ); sensfusion6GetEulerRPY(&stateEstimate.roll, &stateEstimate.pitch, &stateEstimate.yaw); stateEstimate.qw = qw; stateEstimate.qx = qx; stateEstimate.qy = qy; stateEstimate.qz = qz; } }
bool commanderSetSetpoint(const Setpoint *setpoint, int priority) { if (!setpoint) return false; if (priority == COMMANDER_PRIORITY_DISABLE || priority >= activePr) { activeSp = *setpoint; activePr = priority; activeTick = setpoint->timestamp; return true; } return false; }
void commanderRelaxPriority(void) { activePr = COMMANDER_PRIORITY_LOWEST; }
uint32_t commanderGetInactivityTime(void) { return activeTick; }
int commanderGetActivePriority(void) { return activePr; }

void stabilizerInit(void) { static bool initialized; if (initialized) return; sensfusion6Init(); attitudeControllerInit(1.0f / (float)ATTITUDE_RATE_HZ); supervisorInit(); crtpInit(); initialized = true; }
void stabilizerTask(void) { if (hasPendingHighLevel) { commanderSetSetpoint(&pendingHighLevel, COMMANDER_PRIORITY_HIGHLEVEL); hasPendingHighLevel = false; } }
bool stabilizerSubmitHighLevelSetpoint(const Setpoint *setpoint) { if (!setpoint) return false; pendingHighLevel = *setpoint; hasPendingHighLevel = true; return true; }
static uint32_t quatcompress(float w, float x, float y, float z) { uint32_t a = ((uint32_t)((w + 1.0f) * 511.5f)) & 0x3ffU; uint32_t b = ((uint32_t)((x + 1.0f) * 511.5f)) & 0x3ffU; uint32_t c = ((uint32_t)((y + 1.0f) * 511.5f)) & 0x3ffU; uint32_t d = ((uint32_t)((z + 1.0f) * 0.5f)) & 0x1U; return a | (b << 10) | (c << 20) | (d << 30); }
void compressState(const State *state, const SensorData *sensors, CompressedState *output) { if (!state || !sensors || !output) return; output->position_mm[0] = (int32_t)(state->position.x * 1000.0f); output->position_mm[1] = (int32_t)(state->position.y * 1000.0f); output->position_mm[2] = (int32_t)(state->position.z * 1000.0f); output->velocity_mms[0] = (int32_t)(state->velocity.x * 1000.0f); output->velocity_mms[1] = (int32_t)(state->velocity.y * 1000.0f); output->velocity_mms[2] = (int32_t)(state->velocity.z * 1000.0f); output->acceleration_mms2[0] = (int32_t)(sensors->acc.x * 9810.0f); output->acceleration_mms2[1] = (int32_t)(sensors->acc.y * 9810.0f); output->acceleration_mms2[2] = (int32_t)((sensors->acc.z + 1.0f) * 9810.0f); output->gyro_millirad_s[0] = sensors->gyro.x * (float)M_PI / 180.0f * 1000.0f; output->gyro_millirad_s[1] = -sensors->gyro.y * (float)M_PI / 180.0f * 1000.0f; output->gyro_millirad_s[2] = sensors->gyro.z * (float)M_PI / 180.0f * 1000.0f; output->quatCompressed = quatcompress(state->attitudeQuaternion.w, state->attitudeQuaternion.x, state->attitudeQuaternion.y, state->attitudeQuaternion.z); }
bool rateSupervisorValidate(uint32_t measuredRate) { return measuredRate >= 997U && measuredRate <= 1003U; }
void rateSupervisorTask(void) { }

bool healthShallWeRunTest(void) { if (propReq) { propReq = false; healthTestState = configureAcc; motorPass = 0; healthLog.motorTestCount++; return true; } if (batReq) { batReq = false; healthTestState = testBattery; batteryPass = 0; batterySag = 0.0f; return true; } return healthTestState != testDone; }
void healthRequestPropTest(void) { propReq = true; }
void healthRequestBatteryTest(void) { batReq = true; }
void healthRunTests(const SensorData *sensorData) { (void)sensorData; if (healthTestState == configureAcc) healthTestState = measureNoiseFloor; else if (healthTestState == measureNoiseFloor) healthTestState = measureProp; else if (healthTestState == measureProp) healthTestState = evaluatePropResult; else if (healthTestState == evaluatePropResult) healthTestState = testDone; else if (healthTestState == testBattery) healthTestState = evaluateBatResult; else if (healthTestState == evaluateBatResult) { batteryPass = 1; healthTestState = testDone; } healthLog.motorPass = motorPass; healthLog.batteryPass = batteryPass; healthLog.batterySag = batterySag; }
bool evaluatePropTest(float lowThreshold, float highThreshold, float measuredValue, uint8_t motorIndex) { bool ok = highThreshold == 0.0f || (measuredValue >= lowThreshold && measuredValue <= highThreshold); if (ok && motorIndex < 4U) motorPass |= (uint8_t)(1U << motorIndex); return ok; }
float variance(const float *buffer, int length) { if (!buffer || length <= 0) return 0.0f; float sum = 0.0f, sumSq = 0.0f; for (int i = 0; i < length; i++) { sum += buffer[i]; sumSq += buffer[i] * buffer[i]; } return sumSq - (sum * sum / (float)length); }

static CrtpPacket tx[CRTP_TX_QUEUE_SIZE], rx[CRTP_NBR_OF_PORTS][CRTP_RX_QUEUE_SIZE];
static unsigned txh, txt, txc, rh[CRTP_NBR_OF_PORTS], rt[CRTP_NBR_OF_PORTS], rc[CRTP_NBR_OF_PORTS];
static bool rxCreated[CRTP_NBR_OF_PORTS];
static CrtpPortCallback cb[CRTP_NBR_OF_PORTS];
static CrtpLink *link;
static bool queuePush(CrtpPacket *queue, unsigned *tail, unsigned *count, unsigned capacity, const CrtpPacket *packet) { if (!packet || *count >= capacity) return false; queue[*tail] = *packet; *tail = (*tail + 1U) % capacity; (*count)++; return true; }
void crtpInit(void) { static bool initialized; if (initialized) return; txh = txt = txc = 0; memset(rh, 0, sizeof(rh)); memset(rt, 0, sizeof(rt)); memset(rc, 0, sizeof(rc)); memset(rxCreated, 0, sizeof(rxCreated)); memset(cb, 0, sizeof(cb)); initialized = true; }
void crtpInitTaskQueue(uint8_t port) { if (port >= CRTP_NBR_OF_PORTS) return; if (rxCreated[port]) { supervisorConditionBits |= SUPERVISOR_CB_DECK_FAULT; return; } rxCreated[port] = true; rh[port] = rt[port] = rc[port] = 0; }
bool crtpSendPacket(const CrtpPacket *packet) { return queuePush(tx, &txt, &txc, CRTP_TX_QUEUE_SIZE, packet); }
bool crtpSendPacketBlock(const CrtpPacket *packet) { return crtpSendPacket(packet); }
static bool takeRx(uint8_t port, CrtpPacket *packet) { if (port >= CRTP_NBR_OF_PORTS || !packet || rc[port] == 0U) return false; *packet = rx[port][rh[port]]; rh[port] = (rh[port] + 1U) % CRTP_RX_QUEUE_SIZE; rc[port]--; return true; }
bool crtpReceivePacket(uint8_t port, CrtpPacket *packet) { return takeRx(port, packet); }
bool crtpReceivePacketBlock(uint8_t port, CrtpPacket *packet) { return takeRx(port, packet); }
bool crtpReceivePacketWait(uint8_t port, CrtpPacket *packet, uint32_t wait_ms) { (void)wait_ms; return takeRx(port, packet); }
void crtpRxTask(void) { CrtpPacket packet; if (!link || !link->receivePacket) return; if (link->receivePacket(&packet)) { if (packet.port < CRTP_NBR_OF_PORTS && rxCreated[packet.port] && rc[packet.port] < CRTP_RX_QUEUE_SIZE) { rx[packet.port][rt[packet.port]] = packet; rt[packet.port] = (rt[packet.port] + 1U) % CRTP_RX_QUEUE_SIZE; rc[packet.port]++; } if (packet.port < CRTP_NBR_OF_PORTS && cb[packet.port]) cb[packet.port](&packet); } }
void crtpTxTask(void) { if (!link || !link->sendPacket || txc == 0U) return; if (link->sendPacket(&tx[txh])) { txh = (txh + 1U) % CRTP_TX_QUEUE_SIZE; txc--; } }
void crtpSetLink(CrtpLink *newLink) { if (link && link->setEnable) link->setEnable(false); link = newLink; if (link && link->setEnable) link->setEnable(true); }
void crtpReset(void) { txh = txt = txc = 0; if (link && link->reset) link->reset(); }
bool crtpIsConnected(void) { return link && link->isConnected ? link->isConnected() : true; }
uint32_t crtpGetFreeTxQueuePackets(void) { return CRTP_TX_QUEUE_SIZE - txc; }
void crtpRegisterPortCB(uint8_t port, CrtpPortCallback callback) { if (port < CRTP_NBR_OF_PORTS) cb[port] = callback; }
void updateStats(void) { }

uint8_t deckDiscovery(DeckInfo *decks, uint8_t capacity) { if (!decks || capacity == 0U) return 0; uint8_t count = 0; const uint8_t addrs[] = { 0x0aU, 0x0bU, 0x1cU, 0x1dU }; for (unsigned i = 0; i < sizeof(addrs) / sizeof(addrs[0]) && count < capacity; i++) { decks[count].foundByI2C = true; decks[count].foundByOneWire = false; decks[count].i2cAddress = addrs[i]; decks[count].oneWireRomId = 0; count++; } return count; }